import { tokenize, shellQuote } from '../api-client/curl.js';

// Known browser-fingerprinting / transport-metadata headers that add no value when
// sharing a cleaned-up curl command (they're regenerated by whatever actually sends
// the request). Everything NOT in this list - Accept, Content-Type, Authorization,
// and any custom/app-specific header like x-api-key - is kept by default.
const NOISE_HEADERS = new Set([
  'accept-language',
  'origin',
  'referer',
  'priority',
  'sec-ch-ua',
  'sec-ch-ua-mobile',
  'sec-ch-ua-platform',
  'sec-fetch-dest',
  'sec-fetch-mode',
  'sec-fetch-site',
  'user-agent',
  'host',
  'content-length',
  'connection',
  'accept-encoding',
  'cookie',
]);

function looksLikeCmdEscaped(text) {
  return /\^"/.test(text);
}

// Un-escapes Chrome/Edge DevTools' "Copy as cURL (cmd)" export, which caret-escapes
// every special character for cmd.exe safety: `^\^"` is a literal embedded quote
// (e.g. inside a JSON body), a bare `^"` is an argument's opening/closing quote, and
// any other `^X` is just a literal X. `^\^"` collapses to `\"` (escaped quote,
// backslash kept) rather than directly to `"` - otherwise the quote-aware tokenize()
// below can't tell an embedded quote from the argument's real closing quote.
function normalizeCmdEscaping(text) {
  const joined = text.replace(/\^[ \t]*\r?\n[ \t]*/g, ' ');
  let out = '';
  for (let i = 0; i < joined.length; i += 1) {
    if (joined[i] === '^' && joined[i + 1] === '\\' && joined[i + 2] === '^' && joined[i + 3] === '"') {
      out += '\\"';
      i += 3;
    } else if (joined[i] === '^' && i + 1 < joined.length) {
      out += joined[i + 1];
      i += 1;
    } else {
      out += joined[i];
    }
  }
  return out;
}

// Parses a pasted cURL command - either a plain POSIX/bash export or a Windows-cmd
// caret-escaped one (see normalizeCmdEscaping above) - into its logical pieces.
// Deliberately does NOT split the URL's query string out the way api-client/curl.js's
// fromCurl() does: that tool needs query params as independently editable rows, but
// this one only ever echoes the URL back out verbatim, so splitting and reassembling
// it would risk subtly re-encoding it differently than the original.
export function parseRawCurl(rawText) {
  const text = rawText.trim();
  if (!text) {
    return { ok: false, error: 'Paste a cURL command to clean.' };
  }

  const normalized = looksLikeCmdEscaped(text) ? normalizeCmdEscaping(text) : text.replace(/\\\r?\n/g, ' ');
  let tokens = tokenize(normalized.trim());
  if (tokens[0] === 'curl') {
    tokens = tokens.slice(1);
  }

  let method = null;
  let url = null;
  const headers = [];
  let body = null;

  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i];
    if (token === '-X' || token === '--request') {
      method = tokens[(i += 1)] || null;
    } else if (token === '--url') {
      url = tokens[(i += 1)] || null;
    } else if (token === '-H' || token === '--header') {
      const line = tokens[(i += 1)] || '';
      const sep = line.indexOf(':');
      if (sep !== -1) {
        headers.push({ key: line.slice(0, sep).trim(), value: line.slice(sep + 1).trim() });
      }
    } else if (token === '-d' || token === '--data' || token === '--data-raw' || token === '--data-binary') {
      body = tokens[(i += 1)] || '';
    } else if (!url && !token.startsWith('-')) {
      url = token;
    }
  }

  if (!url) {
    return { ok: false, error: 'No URL found in the pasted cURL command.' };
  }

  let bodyIsJson = false;
  if (body) {
    try {
      JSON.parse(body);
      bodyIsJson = true;
    } catch {
      bodyIsJson = false;
    }
  }

  return { ok: true, method, url, headers, body, bodyIsJson };
}

export function classifyHeader(key) {
  return NOISE_HEADERS.has(key.toLowerCase()) ? 'noise' : 'keep';
}

export function titleCaseHeader(key) {
  return key
    .split('-')
    .map((part) => (part ? part.charAt(0).toUpperCase() + part.slice(1).toLowerCase() : part))
    .join('-');
}

export function redactAuthValue(value) {
  if (/^Bearer\s+\S+$/i.test(value)) {
    return 'Bearer <YOUR_ACCESS_TOKEN>';
  }
  if (/^Basic\s+\S+$/i.test(value)) {
    return 'Basic <YOUR_CREDENTIALS>';
  }
  return value;
}

const BODY_INDENT = '  ';

function indentJsonBody(rawBody) {
  const pretty = JSON.stringify(JSON.parse(rawBody), null, 2);
  return pretty
    .split('\n')
    .map((line, index) => (index === 0 ? line : BODY_INDENT + line))
    .join('\n');
}

// Builds the final clean curl text. `headers` must already be filtered (only
// entries the caller wants kept) and already redacted - this function only formats,
// it never decides what to keep or hide.
export function buildCleanCurl({ method, url, headers, body, bodyIsJson }) {
  const lines = [`curl --location ${shellQuote(url)} \\`];
  if (method) {
    lines.push(`${BODY_INDENT}--request ${method} \\`);
  }
  headers.forEach((header) => {
    lines.push(`${BODY_INDENT}--header ${shellQuote(`${titleCaseHeader(header.key)}: ${header.value}`)} \\`);
  });
  if (body) {
    const bodyText = bodyIsJson ? indentJsonBody(body) : body;
    lines.push(`${BODY_INDENT}--data-raw ${shellQuote(bodyText)}`);
  } else {
    lines[lines.length - 1] = lines[lines.length - 1].replace(/ \\$/, '');
  }
  return lines.join('\n');
}
